mapper.update:
UPDATE card_benefit_monthly_usage
SET used_amount = GREATEST(used_amount - #{usedAmount}, 0),
    used_count = GREATEST(used_count - 1, 0),
    updated_at = NOW()
WHERE user_card_id = #{userCardId}
  AND benefit_service_name = #{benefitServiceName}
  AND target_year_month = #{targetYearMonth}

mapper.select:
SELECT benefit_service_name AS benefitServiceName,
       used_amount          AS usedAmount,
       used_count           AS usedCount
FROM card_benefit_monthly_usage
WHERE user_card_id = #{userCardId}
  AND target_year_month = #{targetYearMonth}

SELECT benefit_service_name AS benefitServiceName,
       SUM(used_count)      AS usedCount
FROM card_benefit_monthly_usage
WHERE user_card_id = #{userCardId}
  AND target_year = #{targetYear}
GROUP BY benefit_service_name
